    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h2_1",
        "intro_text",
        "title_h2_2",
        "chart_description",
        "performance_table",
        "correlation_text"
      ]
    },
    "title_h2_1": {
      "type": "Text",
      "props": {
        "text": "Employee Performance Insights",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This analysis examines the relationship between an employee's years of experience and their performance score based on the provided data. The data points indicate a generally increasing trend in performance as experience grows.",
        "variant": "body"
      },
      "children": []
    },
    "title_h2_2": {
      "type": "Text",
      "props": {
        "text": "Experience vs. Performance Data",
        "variant": "h2"
      },
      "children": []
    },
    "chart_description": {
      "type": "Text",
      "props": {
        "text": "The table below visualizes how 'Years of Experience' correlates with 'Performance Score'. Each row represents an employee's data.",
        "variant": "body"
      },
      "children": []
    },
    "performance_table": {
      "type": "Table",
      "props": {
        "statePath": "/chartData",
        "columns": [
          {
            "key": "experience",
            "label": "Years of Experience"
          },
          {
            "key": "performance",
            "label": "Performance Score"
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table",
        "primaryColumn": "experience",
        "highlightColumns": [
          "performance"
        ]
      },
      "children": []
    },
    "correlation_text": {
      "type": "Text",
      "props": {
        "text": "There is a positive correlation between 'Years of Experience' and 'Performance Score'. As an employee's years of experience increase, their performance score generally tends to rise.",
        "variant": "body"
      },
      "children": []
    }
  }
}
